// FormatCSVLine formats a single entry as a CSV line, quoting the memo if
// it contains a comma.
func FormatCSVLine(e Entry) string {
	memo := e.Memo
	if containsComma(memo) {
		memo = "\"" + memo + "\""
	}
	return fmt.Sprintf("%s,%s,%s", e.Date.Format("2006-01-02"), FormatAmount(e.Cents), memo)
}

func containsComma(s string) bool {
	for _, c := range s {
		if c == ',' {
			return true
		}
	}
	return false
}

// Total adds up every entry's amount.
